                    "A) as políticas da empresa",
                    "B) o salário e os benefícios",
                    "C) o reconhecimento, a responsabilidade, o próprio trabalho e as oportunidades de crescimento",
                    "D) as condições físicas do ambiente",
                    "E) a segurança no emprego"
