            {
                "id": 7024,
                "enunciado": "Na teoria das três idades, os documentos frequentemente consultados pelo setor que os produziu, mantidos próximos aos usuários, estão na fase:",
                "opcoes": [
                    "A) histórica",
                    "B) corrente",
                    "C) intermediária",
                    "D) de eliminação",
                    "E) permanente"
                ],
                "correta": 1,
                "comentario": "Na primeira idade (arquivo corrente), o documento é usado com frequência para as atividades que o geraram."
            },
            {
                "id": 7025,
                "enunciado": "Na teoria das três idades, a fase em que os documentos, já com pouco uso, aguardam o cumprimento do prazo de guarda para eliminação ou recolhimento é a:",
                "opcoes": [
                    "A) primária",
                    "B) permanente",
                    "C) intermediária",
                    "D) de produção",
                    "E) corrente"
                ],
                "correta": 2,
                "comentario": "No arquivo intermediário (segunda idade), os documentos são guardados por razões administrativas ou legais até sua destinação final."
            },
            {
                "id": 7026,
                "enunciado": "Os documentos recolhidos ao arquivo permanente:",
                "opcoes": [
                    "A) perdem o caráter de documento público",
                    "B) são vendidos como papel reciclável",
                    "C) voltam ao setor de origem para uso diário",
                    "D) podem ser eliminados após cinco anos",
                    "E) são preservados definitivamente, em razão de seu valor histórico, probatório e informativo"
                ],
                "correta": 4,
                "comentario": "Pela Lei nº 8.159/1991, os documentos permanentes são inalienáveis e imprescritíveis."
            },
            {
                "id": 7027,
                "enunciado": "A operação que leva os documentos do arquivo corrente para o arquivo intermediário denomina-se:",
                "opcoes": [
                    "A) recolhimento",
                    "B) transferência",
                    "C) eliminação",
                    "D) autuação",
                    "E) avaliação"
                ],
                "correta": 1,
                "comentario": "Transferência: corrente → intermediário. Recolhimento: intermediário (ou corrente) → permanente."
            },
            {
                "id": 7028,
                "enunciado": "O recolhimento, na gestão de documentos, é:",
                "opcoes": [
                    "A) a passagem do arquivo corrente para o intermediário",
                    "B) a entrada de documentos no arquivo permanente",
                    "C) a eliminação de documentos sem valor",
                    "D) o recebimento de documentos no protocolo",
                    "E) a retirada de documentos para empréstimo"
                ],
                "correta": 1,
                "comentario": "Recolher é enviar ao arquivo permanente os documentos de guarda definitiva."
            },
            {
                "id": 7029,
                "enunciado": "Entre os objetivos da gestão de documentos está:",
                "opcoes": [
                    "A) dificultar o acesso para proteger os documentos",
                    "B) substituir a necessidade de protocolo",
                    "C) guardar todos os documentos para sempre",
                    "D) eliminar todos os documentos após o uso",
                    "E) racionalizar a produção e o fluxo documental, garantindo o acesso à informação e reduzindo a massa documental acumulada"
                ],
                "correta": 4,
                "comentario": "A gestão de documentos evita acúmulos desnecessários, agiliza a recuperação da informação e assegura a preservação do que tem valor permanente."
            },
            {
                "id": 7030,
                "enunciado": "O setor de protocolo é responsável pelas atividades de:",
                "opcoes": [
                    "A) elaboração das leis do órgão",
                    "B) julgamento de processos administrativos",
                    "C) restauração de documentos permanentes",
                    "D) recebimento, registro, distribuição, controle da tramitação e expedição de documentos",
                    "E) eliminação de documentos sem autorização"
                ],
                "correta": 3,
                "comentario": "O protocolo controla a entrada, a movimentação e a saída dos documentos, mantendo seu registro."
            },
            {
                "id": 7031,
                "enunciado": "No protocolo, o registro de um documento recebido consiste em:",
                "opcoes": [
                    "A) anotar em sistema ou formulário próprio dados como número, data, procedência, espécie e assunto do documento",
                    "B) arquivá-lo imediatamente no arquivo permanente",
                    "C) eliminá-lo depois de digitalizado",
                    "D) devolvê-lo ao remetente sem leitura",
                    "E) enviá-lo diretamente à imprensa"
                ],
                "correta": 0,
                "comentario": "O registro dá ao documento identificação e controle, permitindo localizá-lo durante toda a tramitação."
            },
            {
                "id": 7032,
                "enunciado": "A atividade de protocolo que encaminha os documentos aos setores responsáveis por sua análise ou providência é a:",
                "opcoes": [
                    "A) eliminação",
                    "B) avaliação",
                    "C) distribuição",
                    "D) restauração",
                    "E) expedição"
                ],
                "correta": 2,
                "comentario": "Distribuição é a remessa interna dos documentos aos destinatários. Expedição é o envio de documentos para fora da instituição."
            },
            {
                "id": 7033,
                "enunciado": "O acompanhamento do percurso de um documento desde sua entrada até o cumprimento de sua função, registrando cada setor por onde passou, chama-se:",
                "opcoes": [
                    "A) arranjo",
                    "B) controle da tramitação (ou movimentação)",
                    "C) acondicionamento",
                    "D) higienização",
                    "E) microfilmagem"
                ],
                "correta": 1,
                "comentario": "O controle da tramitação permite saber onde está o documento a qualquer momento e quanto tempo ficou em cada setor."
            },
            {
                "id": 7034,
                "enunciado": "A expedição, como atividade de protocolo, consiste em:",
                "opcoes": [
                    "A) receber documentos de outros órgãos",
                    "B) enviar os documentos produzidos pela instituição aos destinatários externos, com o devido registro",
                    "C) eliminar documentos sem valor",
                    "D) restaurar documentos danificados",
                    "E) classificar os documentos por assunto"
                ],
                "correta": 1,
                "comentario": "Na expedição, o protocolo confere o documento, registra a saída e o envia ao destinatário externo."
            },
            {
                "id": 7035,
                "enunciado": "Ao receber um envelope com a indicação \"CONFIDENCIAL\" endereçado a uma autoridade, o setor de protocolo deve, em regra:",
                "opcoes": [
                    "A) digitalizar o conteúdo antes de entregar",
                    "B) abrir o envelope para classificar o assunto",
                    "C) arquivar o envelope sem informar o destinatário",
                    "D) registrar o recebimento sem abrir o envelope e encaminhá-lo diretamente ao destinatário",
                    "E) devolver o envelope ao remetente"
                ],
                "correta": 3,
                "comentario": "Correspondências sigilosas ou de caráter pessoal são registradas pelo lado externo e entregues fechadas ao destinatário."
            },
            {
                "id": 7036,
                "enunciado": "A AUTUAÇÃO de um documento no protocolo significa:",
                "opcoes": [
                    "A) enviar o documento ao arquivo permanente",
                    "B) eliminar o documento",
                    "C) classificar o documento como sigiloso",
                    "D) formar um processo, com capa, número único de protocolo e folhas numeradas",
                    "E) copiar o documento para outro setor"
                ],
                "correta": 3,
                "comentario": "Autuar é transformar o documento em processo, que passa a ter tramitação controlada e peças juntadas em ordem."
            },
            {
                "id": 7037,
                "enunciado": "A juntada de documentos a um processo em andamento deve:",
                "opcoes": [
                    "A) dispensar qualquer registro",
                    "B) substituir as folhas antigas pelas novas",
                    "C) ocorrer apenas após o arquivamento",
                    "D) ser feita em qualquer ordem, sem numeração",
                    "E) seguir a ordem cronológica, com numeração sequencial das folhas e registro da juntada"
                ],
                "correta": 4,
                "comentario": "A numeração sequencial e o registro preservam a integridade do processo e evitam a retirada ou inclusão indevida de folhas."
            },
            {
                "id": 7038,
                "enunciado": "O DESARQUIVAMENTO de um processo é:",
                "opcoes": [
                    "A) a eliminação do processo",
                    "B) a digitalização do processo",
                    "C) a restauração das folhas danificadas",
                    "D) a transferência para outro órgão",
                    "E) a retirada do processo do arquivo para reabertura ou consulta, com registro do motivo e do responsável"
                ],
                "correta": 4,
                "comentario": "O desarquivamento deve ser registrado, para que se saiba onde está o processo e por que foi retirado."
            },
            {
                "id": 7039,
                "enunciado": "O empréstimo de documentos do arquivo a outros setores deve ser:",
                "opcoes": [
                    "A) feito sem qualquer registro, para agilizar o trabalho",
                    "B) proibido em qualquer situação",
                    "C) definitivo, sem devolução",
                    "D) controlado por registro, com identificação do requisitante, da data de saída e do prazo de devolução",
                    "E) autorizado apenas para pessoas de fora do órgão"
                ],
                "correta": 3,
                "comentario": "O controle do empréstimo evita extravios e permite cobrar a devolução."
            },
            {
                "id": 7040,
                "enunciado": "A instalação de arquivos setoriais junto às unidades que mais utilizam os documentos, com orientação técnica de um arquivo central, caracteriza um sistema:",
                "opcoes": [
                    "A) descentralizado, com coordenação central",
                    "B) privado, de colecionadores",
                    "C) permanente, exclusivamente histórico",
                    "D) totalmente centralizado, sem arquivos setoriais",
                    "E) sem qualquer controle técnico"
                ],
                "correta": 0,
                "comentario": "Na descentralização coordenada, os setores guardam seus documentos correntes, mas seguem normas e orientação do arquivo central."
            },
            {
                "id": 7041,
                "enunciado": "O processo eletrônico adotado nos órgãos federais, como o Sistema Eletrônico de Informações (SEI), contribui para a gestão de documentos porque:",
                "opcoes": [
                    "A) substitui a assinatura das autoridades por sorteio",
                    "B) impede o acesso dos interessados aos documentos",
                    "C) dispensa qualquer regra de classificação e temporalidade",
                    "D) elimina automaticamente todos os documentos após um ano",
                    "E) permite produzir, tramitar e consultar documentos em meio digital, com registro automático das movimentações"
                ],
                "correta": 4,
                "comentario": "O processo eletrônico registra cada tramitação e facilita o acesso, mas continua sujeito às regras de classificação, temporalidade e preservação."
            },
            {
                "id": 7042,
                "enunciado": "A massa documental acumulada (MDA) é um problema comum quando:",
                "opcoes": [
                    "A) documentos se acumulam sem tratamento técnico, sem classificação nem avaliação, dificultando sua localização",
                    "B) os documentos são classificados e avaliados corretamente",
                    "C) os documentos são transferidos nos prazos previstos",
                    "D) a tabela de temporalidade é aplicada regularmente",
                    "E) o protocolo registra todas as entradas"
                ],
                "correta": 0,
                "comentario": "A MDA resulta da ausência de gestão documental e exige trabalho de identificação, classificação e avaliação para ser tratada."
            },
            {
                "id": 7043,
                "enunciado": "A avaliação de documentos é a atividade que:",
                "opcoes": [
                    "A) analisa os documentos para estabelecer seus prazos de guarda e sua destinação, com base nos valores que possuem",
                    "B) verifica a qualidade da redação",
                    "C) define a ordem alfabética das pastas",
                    "D) escolhe a cor das caixas",
                    "E) calcula o custo de cada documento"
                ],
                "correta": 0,
                "comentario": "A avaliação resulta na tabela de temporalidade, indicando quanto tempo guardar cada documento e se será eliminado ou recolhido."
            },
            {
                "id": 7044,
                "enunciado": "A comissão responsável, em cada órgão público, por orientar e realizar a avaliação e a seleção dos documentos, propondo a eliminação dos que não têm valor permanente, é a:",
                "opcoes": [
                    "A) Comissão Parlamentar de Inquérito",
                    "B) Comissão de Licitação",
                    "C) Comissão de Ética Pública",
                    "D) Comissão Processante Disciplinar",
                    "E) Comissão Permanente de Avaliação de Documentos (CPAD)"
                ],
                "correta": 4,
                "comentario": "A CPAD, prevista na regulamentação federal, aplica a tabela de temporalidade e propõe a eliminação conforme os procedimentos legais."
            },
            {
                "id": 7045,
                "enunciado": "Para os órgãos do Poder Executivo federal, a eliminação de documentos públicos deve ser precedida de:",
                "opcoes": [
                    "A) listagem de eliminação aprovada e publicação de edital de ciência de eliminação, com autorização da instituição arquivística competente",
                    "B) leilão dos documentos",
                    "C) consulta às redes sociais",
                    "D) nenhum procedimento formal",
                    "E) simples decisão verbal do chefe do setor"
                ],
                "correta": 0,
                "comentario": "A eliminação segue procedimentos formais: listagem, autorização do Arquivo Nacional (ou instituição competente) e publicação de edital, para dar transparência."
            },
            {
                "id": 7046,
                "enunciado": "A classificação de documentos de arquivo consiste em:",
                "opcoes": [
                    "A) eliminar documentos repetidos",
                    "B) agrupar os documentos de acordo com as funções e atividades que os geraram, segundo um plano ou código de classificação",
                    "C) ordenar os documentos apenas pela cor da pasta",
                    "D) restaurar documentos rasgados",
                    "E) separar os documentos pelo tamanho"
                ],
                "correta": 1,
                "comentario": "A classificação organiza os documentos pela função e atividade de origem, usando instrumentos como o código de classificação."
            },
            {
                "id": 7047,
                "enunciado": "No Código de Classificação de Documentos de Arquivo para a administração pública, as atividades-meio estão agrupadas, por exemplo, na classe:",
                "opcoes": [
                    "A) 900 — Assuntos Diversos",
                    "B) 700 — Documentos Pessoais",
                    "C) 500 — Legislação Estrangeira",
                    "D) 100 — Atividades-fim de cada órgão, obrigatoriamente",
                    "E) 000 — Administração Geral"
                ],
                "correta": 4,
                "comentario": "No código do CONARQ para as atividades-meio, a classe 000 corresponde à Administração Geral (organização, pessoal, material, patrimônio, comunicações etc.)."
            },
            {
                "id": 7048,
                "enunciado": "O código de classificação de documentos baseado no método decimal permite:",
                "opcoes": [
                    "A) calcular o valor de venda dos documentos",
                    "B) ordenar documentos apenas pela data",
                    "C) identificar o peso de cada documento",
                    "D) dispensar a tabela de temporalidade",
                    "E) organizar os assuntos em classes, subclasses, grupos e subgrupos, do geral para o específico"
                ],
                "correta": 4,
                "comentario": "O método decimal divide o conhecimento em dez classes, que se desdobram em subclasses, grupos e subgrupos."
            },
            {
                "id": 7049,
                "enunciado": "O método de arquivamento que ordena os documentos pelo nome das pessoas ou instituições, seguindo a ordem do alfabeto, é o:",
                "opcoes": [
                    "A) numérico cronológico",
                    "B) geográfico",
                    "C) alfabético",
                    "D) ideográfico",
                    "E) dígito-terminal"
                ],
                "correta": 2,
                "comentario": "No método alfabético, a chave de busca é o nome. É um método direto, pois não exige índice para localizar o documento."
            },
            {
                "id": 7050,
                "enunciado": "No arquivamento alfabético de nomes de pessoas físicas, a regra geral é considerar:",
                "opcoes": [
                    "A) sempre o primeiro nome, como em \"João Pereira Silva\"",
                    "B) o sobrenome do meio",
                    "C) apenas as iniciais do nome",
                    "D) o último sobrenome e depois o prenome, como em \"SILVA, João Pereira\"",
                    "E) o nome do cônjuge"
                ],
                "correta": 3,
                "comentario": "Pela regra geral de alfabetação, ordena-se pelo último sobrenome, seguido do prenome e dos demais sobrenomes."
            },
            {
                "id": 7051,
                "enunciado": "Na alfabetação, os sobrenomes compostos por um substantivo e um adjetivo, como \"Castelo Branco\", ou ligados por hífen, como \"Villa-Lobos\":",
                "opcoes": [
                    "A) são ignorados no arquivamento",
                    "B) não se separam, sendo considerados como um só sobrenome",
                    "C) são separados e considera-se apenas o último termo",
                    "D) devem ser abreviados",
                    "E) são registrados apenas pelo primeiro termo"
                ],
                "correta": 1,
                "comentario": "Pela regra, \"Castelo Branco\" e \"Villa-Lobos\" são entradas únicas: CASTELO BRANCO, Humberto; VILLA-LOBOS, Heitor."
            },
            {
                "id": 7052,
                "enunciado": "Nos nomes com partículas de parentesco como \"Filho\", \"Júnior\" e \"Neto\", a regra de alfabetação determina que:",
                "opcoes": [
                    "A) o termo \"Filho\" seja usado como entrada principal",
                    "B) o nome seja arquivado pelo nome do pai",
                    "C) o nome seja arquivado pelo prenome",
                    "D) esses termos acompanhem o último sobrenome, não sendo considerados isoladamente na ordenação",
                    "E) o termo seja ignorado e eliminado do registro"
                ],
                "correta": 3,
                "comentario": "Exemplo: \"Antônio Almeida Filho\" é arquivado como ALMEIDA FILHO, Antônio."
            },
            {
                "id": 7053,
                "enunciado": "O método de arquivamento que organiza os documentos por local de procedência ou destino, como estado, cidade ou país, é o:",
                "opcoes": [
                    "A) ideográfico",
                    "B) geográfico",
                    "C) alfabético onomástico",
                    "D) numérico simples",
                    "E) cronológico"
                ],
                "correta": 1,
                "comentario": "O método geográfico é indicado quando a localização é o principal elemento de busca, como correspondências de diversas regionais."
            },
            {
                "id": 7054,
                "enunciado": "No método numérico simples, os documentos recebem números em ordem sequencial e a localização depende, em regra:",
                "opcoes": [
                    "A) apenas da memória do arquivista",
                    "B) da cor da pasta",
                    "C) de um índice auxiliar que relacione os nomes ou assuntos aos números",
                    "D) do tamanho do documento",
                    "E) da data de nascimento do interessado"
                ],
                "correta": 2,
                "comentario": "Os métodos numéricos são indiretos: é preciso consultar um índice para saber qual número corresponde a cada nome ou assunto."
            },
            {
                "id": 7055,
                "enunciado": "O método DÍGITO-TERMINAL, utilizado em arquivos com grande volume de documentos numerados, caracteriza-se por:",
                "opcoes": [
                    "A) ordenar os documentos pelo primeiro dígito, da esquerda para a direita",
                    "B) ordenar os documentos por assunto",
                    "C) dispensar qualquer numeração",
                    "D) ler o número em grupos de dois dígitos, da direita para a esquerda, distribuindo os documentos de forma mais equilibrada",
                    "E) agrupar os documentos pela cor"
                ],
                "correta": 3,
                "comentario": "No dígito-terminal, o número 829.546 é lido como 46-95-82, começando pelos dígitos finais, o que reduz erros e distribui melhor o acervo."
            },
            {
                "id": 7056,
                "enunciado": "O método de arquivamento que organiza os documentos por assuntos é chamado de:",
                "opcoes": [
                    "A) ideográfico",
                    "B) onomástico",
                    "C) numérico simples",
                    "D) geográfico",
                    "E) cronológico"
                ],
                "correta": 0,
                "comentario": "No método ideográfico (por assunto), os temas podem ser ordenados alfabeticamente (enciclopédico ou dicionário) ou numericamente (decimal, duplex)."
            },
            {
                "id": 7057,
                "enunciado": "Na ordenação cronológica de documentos, o critério utilizado é:",
                "opcoes": [
                    "A) o nome do remetente",
                    "B) a cidade de origem",
                    "C) o número de páginas",
                    "D) o assunto",
                    "E) a data do documento"
                ],
                "correta": 4,
                "comentario": "A ordem cronológica segue as datas, sendo comum em processos e em documentos de um mesmo assunto."
            },
            {
                "id": 7058,
                "enunciado": "A tabela de temporalidade de documentos é o instrumento que:",
                "opcoes": [
                    "A) organiza o calendário de feriados",
                    "B) registra o empréstimo de livros",
                    "C) define os prazos de guarda nas fases corrente e intermediária e a destinação final dos documentos (eliminação ou guarda permanente)",
                    "D) define o preço de venda dos documentos",
                    "E) lista os servidores do arquivo e seus horários"
                ],
                "correta": 2,
                "comentario": "A tabela de temporalidade é resultado da avaliação e orienta quanto tempo guardar cada tipo documental e o que fazer depois."
            },
            {
                "id": 7059,
                "enunciado": "Na tabela de temporalidade, a coluna \"destinação final\" indica se o documento será:",
                "opcoes": [
                    "A) traduzido ou resumido",
                    "B) copiado ou emprestado",
                    "C) restaurado ou plastificado",
                    "D) eliminado ou recolhido para guarda permanente",
                    "E) vendido ou doado"
                ],
                "correta": 3,
                "comentario": "A destinação final define o destino do documento após cumprir os prazos de guarda."
            },
            {
                "id": 7060,
                "enunciado": "Um documento cuja tabela de temporalidade prevê \"5 anos na fase corrente, 5 anos na fase intermediária e eliminação\" deverá ser guardado, no total, por:",
                "opcoes": [
                    "A) 10 anos antes de ser eliminado",
                    "B) 1 ano e depois transferido",
                    "C) tempo indeterminado",
                    "D) 5 anos antes de ser eliminado",
                    "E) 15 anos e recolhido ao permanente"
                ],
                "correta": 0,
                "comentario": "Somam-se os prazos das duas fases: 5 + 5 = 10 anos. Após esse período, observados os procedimentos legais, o documento pode ser eliminado."
            },
            {
                "id": 7061,
                "enunciado": "A temporalidade dos documentos de arquivo deve ser definida com base:",
                "opcoes": [
                    "A) na cor da pasta",
                    "B) na preferência pessoal do arquivista",
                    "C) nos prazos legais, nas necessidades administrativas e no valor histórico ou informativo dos documentos",
                    "D) no tamanho do documento",
                    "E) no espaço disponível nas estantes, apenas"
                ],
                "correta": 2,
                "comentario": "A avaliação considera exigências legais (prescrição, fiscalização), uso administrativo e valor para a pesquisa e a memória."
            },
            {
                "id": 7062,
                "enunciado": "O arranjo, nos arquivos permanentes, corresponde:",
                "opcoes": [
                    "A) ao registro de entrada no protocolo",
                    "B) à organização dos documentos de acordo com os princípios arquivísticos, especialmente o respeito aos fundos",
                    "C) à digitalização de todo o acervo",
                    "D) à eliminação de documentos sem valor",
                    "E) à restauração dos documentos danificados"
                ],
                "correta": 1,
                "comentario": "Arranjo é a organização intelectual e física dos documentos permanentes, respeitando a proveniência e a ordem original."
            },
            {
                "id": 7063,
                "enunciado": "A descrição arquivística tem como principal finalidade:",
                "opcoes": [
                    "A) emprestar documentos",
                    "B) elaborar instrumentos de pesquisa, como guias, inventários e catálogos, que permitem localizar e conhecer os documentos",
                    "C) eliminar documentos",
                    "D) definir os prazos de guarda",
                    "E) higienizar os documentos"
                ],
                "correta": 1,
                "comentario": "A descrição produz representações dos documentos que facilitam o acesso e a pesquisa, especialmente nos arquivos permanentes."
            },
            {
                "id": 7064,
                "enunciado": "O instrumento de pesquisa mais abrangente, que fornece informações gerais sobre os fundos e coleções de um arquivo, é o:",
                "opcoes": [
                    "A) repertório de uma única série",
                    "B) índice onomástico",
                    "C) termo de transferência",
                    "D) catálogo de peças individuais",
                    "E) guia"
                ],
                "correta": 4,
                "comentario": "O guia oferece visão geral do acervo. Inventários e catálogos detalham progressivamente as séries e os documentos."
            },
            {
                "id": 7065,
                "enunciado": "O \"arquivamento\" de um processo, na rotina administrativa, significa:",
                "opcoes": [
                    "A) interromper o processo antes da decisão",
                    "B) enviar o processo à imprensa",
                    "C) eliminar o processo imediatamente",
                    "D) guardar o processo após a conclusão de sua tramitação, observados os critérios de classificação e temporalidade",
                    "E) devolver o processo ao interessado em definitivo"
                ],
                "correta": 3,
                "comentario": "Arquivar é guardar o documento de forma organizada, para que possa ser localizado e destinado conforme a tabela de temporalidade."
            },
            {
                "id": 7066,
                "enunciado": "Para facilitar a recuperação de documentos arquivados pelo método numérico, utiliza-se como instrumento auxiliar:",
                "opcoes": [
                    "A) o índice remissivo, que relaciona nomes ou assuntos aos números atribuídos",
                    "B) o termo de eliminação",
                    "C) a tabela de cores",
                    "D) o organograma",
                    "E) o código de ética"
                ],
                "correta": 0,
                "comentario": "O índice faz a ligação entre o elemento de busca (nome ou assunto) e o número de arquivamento."
            },
            {
                "id": 7067,
                "enunciado": "Na alfabetação, os artigos e preposições como \"de\", \"da\", \"do\" e \"e\", quando fazem parte de sobrenomes:",
                "opcoes": [
                    "A) substituem o último sobrenome",
                    "B) tornam o nome impossível de arquivar",
                    "C) não são considerados na ordenação alfabética",
                    "D) devem ser escritos em maiúsculas e ordenados primeiro",
                    "E) são considerados como a primeira palavra do nome"
                ],
                "correta": 2,
                "comentario": "Pela regra, \"Maria da Silva\" é ordenada como SILVA, Maria da, sem considerar a preposição."
            },
            {
                "id": 7068,
                "enunciado": "O ACONDICIONAMENTO de documentos consiste em:",
                "opcoes": [
                    "A) registrar a entrada do documento",
                    "B) definir o prazo de guarda",
                    "C) embalar ou guardar os documentos em invólucros adequados, como pastas, caixas e envelopes, para protegê-los",
                    "D) traduzir documentos estrangeiros",
                    "E) eliminar os documentos sem valor"
                ],
                "correta": 2,
                "comentario": "O acondicionamento protege o documento diretamente, com materiais adequados ao seu suporte e formato."
            },
            {
                "id": 7069,
                "enunciado": "O ARMAZENAMENTO de documentos refere-se:",
                "opcoes": [
                    "A) à escolha do tipo de pasta",
                    "B) à guarda dos documentos acondicionados em mobiliário e espaço físico adequados, como estantes e depósitos",
                    "C) ao registro no protocolo",
                    "D) à numeração das folhas",
                    "E) à avaliação dos documentos"
                ],
                "correta": 1,
                "comentario": "Armazenar é colocar os documentos já acondicionados em estantes, arquivos e depósitos com condições ambientais adequadas."
            },
            {
                "id": 7070,
                "enunciado": "Para o acondicionamento de documentos de valor permanente, recomenda-se utilizar materiais:",
                "opcoes": [
                    "A) de madeira não tratada",
                    "B) com reserva alcalina ou neutros, livres de ácidos",
                    "C) plásticos de qualquer tipo, sem critério",
                    "D) ácidos, como papel jornal",
                    "E) com fitas adesivas comuns"
                ],
                "correta": 1,
                "comentario": "Materiais ácidos aceleram a degradação do papel. Caixas e pastas neutras ou alcalinas ajudam a preservar o acervo."
            },
            {
                "id": 7071,
                "enunciado": "O uso de clipes e grampos metálicos em documentos de guarda permanente deve ser evitado porque:",
                "opcoes": [
                    "A) podem enferrujar e manchar ou rasgar o papel",
                    "B) impedem a leitura do documento",
                    "C) são proibidos em qualquer documento público",
                    "D) dificultam a classificação por assunto",
                    "E) aumentam o valor histórico do documento"
                ],
                "correta": 0,
                "comentario": "A oxidação do metal danifica o papel. Para guarda permanente, recomenda-se substituí-los por clipes plásticos ou outros materiais inertes."
            },
            {
                "id": 7072,
                "enunciado": "A aplicação de fita adesiva comum para reparar documentos rasgados é desaconselhada porque:",
                "opcoes": [
                    "A) protege o documento contra fungos",
                    "B) é o método recomendado pelos restauradores",
                    "C) torna o documento mais resistente para sempre",
                    "D) o adesivo se degrada com o tempo, amarelando e manchando o papel de forma irreversível",
                    "E) facilita a digitalização"
                ],
                "correta": 3,
                "comentario": "Fitas adesivas comuns causam manchas e danos irreversíveis. Reparos devem ser feitos com técnicas e materiais de conservação adequados."
            },
            {
                "id": 7073,
                "enunciado": "A preservação de documentos compreende:",
                "opcoes": [
                    "A) apenas a eliminação de documentos",
                    "B) apenas a restauração de documentos danificados",
                    "C) exclusivamente a plastificação dos documentos",
                    "D) somente a digitalização do acervo",
                    "E) o conjunto de medidas e estratégias administrativas, políticas e operacionais que contribuem, direta ou indiretamente, para a proteção do acervo"
                ],
                "correta": 4,
                "comentario": "Preservação é o conceito mais amplo, que inclui políticas, controle ambiental, segurança, conservação e restauração."
            },
            {
                "id": 7074,
                "enunciado": "A CONSERVAÇÃO de documentos, diferentemente da restauração, envolve:",
                "opcoes": [
                    "A) a eliminação de documentos",
                    "B) a mudança do conteúdo do documento",
                    "C) a recuperação de documentos já muito danificados, por intervenção direta",
                    "D) ações preventivas para retardar a deterioração, como controle ambiental, higienização e acondicionamento adequado",
                    "E) a substituição do original por cópia"
                ],
                "correta": 3,
                "comentario": "A conservação é preventiva. A restauração é corretiva, intervindo em documentos já danificados para recuperar sua integridade."
            },
            {
                "id": 7075,
                "enunciado": "A RESTAURAÇÃO de documentos é:",
                "opcoes": [
                    "A) a eliminação de documentos sem valor",
                    "B) o registro no protocolo",
                    "C) o conjunto de procedimentos para recuperar documentos danificados, devolvendo-lhes estabilidade física, sempre que possível com intervenções reversíveis",
                    "D) a definição do prazo de guarda",
                    "E) a guarda do documento em caixa"
                ],
                "correta": 2,
                "comentario": "A restauração atua diretamente no documento danificado e deve ser feita por profissional especializado, com materiais e técnicas adequados."
            },
            {
                "id": 7076,
                "enunciado": "Os principais fatores ambientais que causam a deterioração dos documentos são:",
                "opcoes": [
                    "A) a quantidade de páginas e o idioma",
                    "B) temperatura e umidade relativa inadequadas, luz, poluição atmosférica e agentes biológicos",
                    "C) o número de leitores e a cor das pastas",
                    "D) o tamanho da letra e a fonte usada",
                    "E) a organização alfabética e a numeração"
                ],
                "correta": 1,
                "comentario": "Calor, umidade, luz (especialmente ultravioleta), poluentes e pragas (fungos, insetos, roedores) estão entre os maiores inimigos dos acervos."
            },
            {
                "id": 7077,
                "enunciado": "A umidade relativa do ar muito elevada em um depósito de arquivo favorece, principalmente:",
                "opcoes": [
                    "A) a eliminação dos insetos",
                    "B) a conservação perfeita do acervo",
                    "C) o desenvolvimento de fungos e mofo nos documentos",
                    "D) o desbotamento das tintas pela luz",
                    "E) o ressecamento e a fragilidade do papel, apenas"
                ],
                "correta": 2,
                "comentario": "Umidade alta favorece fungos e bactérias. Umidade muito baixa resseca o papel. O ideal é manter a umidade estável e controlada."
            },
            {
                "id": 7078,
                "enunciado": "A variação brusca de temperatura e umidade nos depósitos de arquivo é prejudicial porque:",
                "opcoes": [
                    "A) elimina automaticamente os fungos",
                    "B) provoca dilatação e contração dos materiais, acelerando a deterioração do papel",
                    "C) melhora a resistência do papel",
                    "D) aumenta o valor histórico dos documentos",
                    "E) não tem qualquer efeito sobre os documentos"
                ],
                "correta": 1,
                "comentario": "A estabilidade ambiental é tão importante quanto os valores ideais: oscilações constantes estressam os suportes."
            },
            {
                "id": 7079,
                "enunciado": "A exposição direta dos documentos à luz solar deve ser evitada porque:",
                "opcoes": [
                    "A) a radiação ultravioleta provoca desbotamento das tintas e enfraquecimento do papel",
                    "B) a luz não afeta documentos em papel",
                    "C) a luz solar elimina os fungos sem causar danos",
                    "D) o papel se torna mais flexível",
                    "E) a luz melhora a legibilidade de forma permanente"
                ],
                "correta": 0,
                "comentario": "A luz, sobretudo a ultravioleta, causa danos cumulativos e irreversíveis. Recomenda-se iluminação controlada nos depósitos."
            },
            {
                "id": 7080,
                "enunciado": "A HIGIENIZAÇÃO de documentos tem como objetivo:",
                "opcoes": [
                    "A) colorir documentos desbotados",
                    "B) apagar informações desnecessárias",
                    "C) remover poeira, partículas e outros resíduos que favorecem a deterioração",
                    "D) alterar a classificação",
                    "E) eliminar documentos repetidos"
                ],
                "correta": 2,
                "comentario": "A higienização, feita com trinchas, aspiradores adequados e cuidado, retira sujidades que atraem pragas e aceleram a degradação."
            },
            {
                "id": 7081,
                "enunciado": "Para prevenir o ataque de insetos e roedores aos acervos, é recomendado:",
                "opcoes": [
                    "A) empilhar os documentos no chão",
                    "B) guardar alimentos junto aos documentos para desviar os insetos",
                    "C) proibir alimentos nos depósitos, manter a limpeza e realizar inspeções e controle integrado de pragas",
                    "D) manter as janelas sempre abertas",
                    "E) aumentar a umidade do ambiente"
                ],
                "correta": 2,
                "comentario": "Alimentos, sujeira e umidade atraem pragas. A prevenção envolve limpeza, inspeção e controle ambiental."
            },
            {
                "id": 7082,
                "enunciado": "No armazenamento, recomenda-se que as caixas de arquivo:",
                "opcoes": [
                    "A) fiquem em estantes, afastadas do chão e das paredes, sem excesso de peso nas prateleiras",
                    "B) fiquem próximas a encanamentos",
                    "C) sejam empilhadas diretamente no chão",
                    "D) fiquem encostadas em paredes úmidas",
                    "E) sejam guardadas sob janelas com sol direto"
                ],
                "correta": 0,
                "comentario": "Manter distância do piso e das paredes reduz riscos de umidade, infiltrações e inundações."
            },
            {
                "id": 7083,
                "enunciado": "As estantes metálicas são geralmente preferidas às de madeira nos depósitos de arquivo porque:",
                "opcoes": [
                    "A) absorvem a umidade do ambiente",
                    "B) são mais baratas em qualquer situação",
                    "C) são menos sujeitas ao ataque de insetos e à propagação de fogo",
                    "D) dispensam qualquer manutenção",
                    "E) liberam substâncias que protegem o papel"
                ],
                "correta": 2,
                "comentario": "A madeira pode atrair cupins e é combustível. Estantes metálicas com pintura adequada são mais seguras para acervos."
            },
            {
                "id": 7084,
                "enunciado": "Documentos fotográficos e audiovisuais exigem, em geral:",
                "opcoes": [
                    "A) armazenamento junto a produtos químicos de limpeza",
                    "B) guarda em ambientes quentes e úmidos",
                    "C) exposição constante à luz para não perderem a imagem",
                    "D) exatamente as mesmas condições de qualquer papel, sem diferença",
                    "E) condições específicas de temperatura e umidade, normalmente mais baixas e controladas que as do papel"
                ],
                "correta": 4,
                "comentario": "Suportes fotográficos e magnéticos são sensíveis e costumam exigir ambientes mais frios e estáveis."
            },
            {
                "id": 7085,
                "enunciado": "A digitalização de documentos, do ponto de vista da preservação, é útil porque:",
                "opcoes": [
                    "A) autoriza a eliminação imediata de todos os originais",
                    "B) torna desnecessária a conservação do papel",
                    "C) reduz o manuseio dos originais e amplia o acesso, sem substituir a necessidade de preservar os originais conforme a legislação",
                    "D) garante a preservação eterna dos arquivos digitais sem cuidados",
                    "E) dispensa a gestão documental"
                ],
                "correta": 2,
                "comentario": "A digitalização protege os originais do manuseio. Mas os arquivos digitais também precisam de preservação (migração de formatos, backups) e os originais seguem as regras de destinação."
            },
            {
                "id": 7086,
                "enunciado": "A preservação digital exige, entre outras medidas:",
                "opcoes": [
                    "A) nunca revisar as mídias de armazenamento",
                    "B) apagar os metadados para economizar espaço",
                    "C) usar apenas formatos proprietários sem documentação",
                    "D) guardar arquivos em um único pendrive, sem cópias",
                    "E) cópias de segurança, uso de formatos abertos ou de longa duração e migração periódica para novas mídias e formatos"
                ],
                "correta": 4,
                "comentario": "Mídias e formatos ficam obsoletos. A preservação digital depende de redundância, padronização e migrações planejadas."
            },
            {
                "id": 7087,
                "enunciado": "Em caso de documentos molhados após uma inundação, a medida inicial mais adequada é:",
                "opcoes": [
                    "A) eliminá-los imediatamente, sem avaliação",
                    "B) deixá-los empilhados para secarem sozinhos",
                    "C) colocá-los ao sol forte sobre o asfalto",
                    "D) retirá-los da área afetada e secá-los ou congelá-los o quanto antes, sob orientação técnica, para evitar fungos",
                    "E) passar ferro quente em cada folha"
                ],
                "correta": 3,
                "comentario": "Em sinistros com água, a rapidez é essencial: em pouco tempo surgem fungos. A secagem ou o congelamento controlado permitem salvar boa parte do acervo."
            },
            {
                "id": 7088,
                "enunciado": "A plastificação de documentos de valor permanente:",
                "opcoes": [
                    "A) é desaconselhada, porque o processo usa calor e adesivos e é, em regra, irreversível",
                    "B) é a melhor forma de preservação a longo prazo",
                    "C) é obrigatória para documentos históricos",
                    "D) impede totalmente a deterioração do papel",
                    "E) é recomendada pelos restauradores para todos os casos"
                ],
                "correta": 0,
                "comentario": "A plastificação pode danificar o papel e não permite remoção segura. A conservação prefere intervenções reversíveis e acondicionamento adequado."
            },
            {
                "id": 7089,
                "enunciado": "O plano de prevenção de riscos e de emergências para um arquivo deve prever, entre outros pontos:",
                "opcoes": [
                    "A) apenas a compra de mais estantes",
                    "B) identificação de riscos como incêndio e inundação, rotas de evacuação e prioridades de salvamento do acervo",
                    "C) a eliminação dos documentos mais antigos",
                    "D) a proibição de qualquer consulta ao acervo",
                    "E) somente a contratação de seguro para os móveis"
                ],
                "correta": 1,
                "comentario": "Planejar a resposta a emergências reduz perdas e define quais documentos devem ser salvos primeiro."
            },
            {
                "id": 7090,
                "enunciado": "Assinale a prática INADEQUADA à conservação de documentos em papel:",
                "opcoes": [
                    "A) usar caixas de tamanho adequado ao documento",
                    "B) manusear documentos com as mãos limpas",
                    "C) evitar a luz solar direta",
                    "D) manter o ambiente limpo e arejado",
                    "E) dobrar documentos grandes várias vezes para caberem em pastas pequenas"
                ],
                "correta": 4,
                "comentario": "Dobras repetidas enfraquecem as fibras e podem rasgar o papel. Documentos grandes devem ser acondicionados em invólucros de tamanho adequado."
            }
